-- EXP09 public coverage in the one original Skills catalogue. Limited means
-- the verified original owner Chat read/private text subset, not recipe execution,
-- a filed document, client delivery or permission. No runtime/activation changes.
-- Requires the preceding original game-plan descriptive correction140000.
UPDATE public.paige_skills AS skill
SET description = coverage.description,
    metadata = coalesce(skill.metadata, '{}'::jsonb) || jsonb_build_object(
      'catalogue_coverage', jsonb_build_object('version', 1, 'state', 'limited'))
FROM (VALUES
  ('build_game_plan', 'Build Step-by-Step Game Plan', 'Prepares a private client-service game-plan draft from the selected CRM customer, the owner brief and available authorized confirmed historical context. Records the draft on its original skill run for business review. Does not assign work, teach Memory, publish, share or send it.', 'Prepares a private client-service game-plan draft from the selected CRM customer, the owner brief and available authorized confirmed historical context. Records the draft on its original skill run for business review. Does not assign work, teach Memory, publish, share or send it.', 2),
  ('client_deliverable_draft', 'Client Deliverable Drafter', 'Drafts the specific deliverable a tenant''s offer produces for a client — an assessment, a plan, a report — grounded in the tenant''s offer and this client''s own context, and renders it as a document for review. It produces an approval-ready draft; the human reviews and approves before it reaches the client.', 'Ask PAIGE to outline a client deliverable for your review. A rendered document, saved deliverable and approved client handoff are not verified by this private Chat outline.', 1),
  ('client_onboarding_sequence', 'New Client Kickoff Journey Drafter', 'Drafts the orchestrated multi-touch kickoff journey for a new client — the welcome touch, the intake questions to send, expectation-setting, and the first milestone — as one approval-ready sequence a human signs off on before anything goes out. This is the multi-step JOURNEY across time, distinct from the static draft_onboarding_packet (a one-time bundle of onboarding documents); this skill orchestrates the touches, it does not assemble the packet.', 'Ask PAIGE to outline a proposed kickoff journey for review. Steps are suggestions until agreed; this does not send an invitation, enroll a client or schedule appointments.', 1),
  ('engagement_wrapup_sequence', 'Engagement Graduation Flow Drafter', 'Drafts the end-of-engagement graduation flow for a client as one approval-ready sequence — a results recap, final handoffs, a renewal or next-step offer, and a testimonial ask. It orchestrates the pieces and sequences them; it references draft_offboarding_document for the formal offboarding document and draft_testimonial_interview_outline for the testimonial questions rather than re-drafting either.', 'Ask PAIGE to outline a conditional engagement wrap-up for review. Recorded outcomes and completion criteria must support any claim; this does not graduate a client or trigger messages.', 1),
  ('milestone_tracking', 'Client Delivery Status Reader', 'Reads where each active client sits in their delivery journey and returns a plain-language status summary — on-track, at-risk, or stalled — with the signal behind each call. Read-only: it inspects client data and journey state and reports; it saves nothing and sends nothing.', 'Ask PAIGE where one client stands to read their saved terms, signatures, invoice facts and delivery work. Missing records stay explicit; checking changes nothing and does not classify churn risk.', 1),
  ('progress_checkin_draft', 'Client Progress Check-in Drafter', 'Drafts a periodic progress check-in message for a client on the engagement''s cadence — what''s been done, what''s next, and one clear ask — in the tenant''s voice. It produces an approval-ready message; after the human approves, the actual send happens through the compose-email seam.', 'Ask PAIGE for a private check-in draft using recorded progress or your brief. It does not send; recipient consent and approval stay with the original communications workflow.', 1),
  ('reactivation_sequence', 'Lapsed Client Win-Back Drafter', 'Drafts a win-back sequence for a lapsed client — a personalized re-engagement message that references their prior work plus a low-friction re-entry offer — as an approval-ready draft. It references crm_search_contacts to identify lapsed clients and the compose-email seam for the downstream send after the human approves.', 'Ask PAIGE to draft a possible re-engagement message for review. Lapse and outreach permission require evidence; no client is marked at risk and no message is sent.', 1)
) AS coverage(slug, canonical_name, original_description, description, original_version)
WHERE skill.slug = coverage.slug
  AND skill.name = coverage.canonical_name
  AND skill.description = coverage.original_description
  AND skill.version = coverage.original_version
  AND skill.category = 'client_delivery'
  AND skill.scoping = 'platform' AND skill.created_by = 'system'
  AND (skill.metadata IS NULL OR jsonb_typeof(skill.metadata) = 'object')
  AND NOT coalesce(skill.metadata ? 'catalogue_coverage', false);
